        'packages'=>$this->rows("SELECT LOWER(HEX(id)) id,LOWER(HEX(baseline_id)) baselineId,title,project_region projectRegion,status,version,snapshot_sha256 snapshotSha256 FROM supplier_integration_packages WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC",$o,$p),
        'matches'=>$this->rows("SELECT LOWER(HEX(m.id)) id,LOWER(HEX(m.package_id)) packageId,LOWER(HEX(m.package_line_id)) packageLineId,LOWER(HEX(m.catalogue_item_id)) catalogueItemId,m.score,m.risk_flags riskFlags,m.latest_order_date latestOrderDate,m.advisory_only advisoryOnly,m.price_cents_snapshot priceCents FROM supplier_catalogue_matches m WHERE m.organisation_id=UNHEX(:o) AND m.project_id=UNHEX(:p) ORDER BY m.score DESC",$o,$p,['riskFlags']),
        'rfqs'=>$this->rows("SELECT LOWER(HEX(id)) id,LOWER(HEX(package_id)) packageId,LOWER(HEX(supplier_id)) supplierId,status,expires_at expiresAt FROM supplier_rfqs WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY issued_at DESC",$o,$p),
        'quotes'=>$this->rows("SELECT LOWER(HEX(q.id)) id,LOWER(HEX(q.rfq_id)) rfqId,q.revision,q.quote_reference quoteReference,q.total_cents totalCents,q.snapshot_sha256 snapshotSha256 FROM supplier_quote_revisions q WHERE q.organisation_id=UNHEX(:o) AND q.project_id=UNHEX(:p) ORDER BY q.submitted_at DESC",$o,$p),
        'purchaseOrders'=>$this->rows("SELECT LOWER(HEX(id)) id,LOWER(HEX(package_id)) packageId,order_number orderNumber,status,total_cents totalCents,snapshot_sha256 snapshotSha256 FROM supplier_purchase_orders WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY issued_at DESC",$o,$p),
        'deliveries'=>$this->rows("SELECT LOWER(HEX(id)) id,LOWER(HEX(purchase_order_id)) purchaseOrderId,delivery_reference deliveryReference,status,version FROM supplier_deliveries WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC",$o,$p),
