        'invoices'=>$this->rows("SELECT LOWER(HEX(id)) id,LOWER(HEX(purchase_order_id)) purchaseOrderId,invoice_number invoiceNumber,amount_cents amountCents,status FROM supplier_invoices WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC",$o,$p),
        'paymentRecommendations'=>$this->rows("SELECT LOWER(HEX(id)) id,LOWER(HEX(invoice_id)) invoiceId,decision,reason,provider_status providerStatus,moves_money movesMoney,snapshot_sha256 snapshotSha256 FROM supplier_payment_recommendations WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC",$o,$p),
        'availableFiles'=>$this->rows("SELECT LOWER(HEX(id)) id,original_name originalName,mime_type mimeType,byte_size byteSize,sha256 FROM stored_files WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC LIMIT 200",$o,$p),
        'access'=>['role'=>$role,'canOperate'=>$role!=='viewer','canApprove'=>in_array($role,['owner','admin'],true)],
