    /** @param array<string,mixed>$in @return array<string,mixed> */public function registerSupplier(string$o,string$u,string$role,string$p,array$in):array{$this->scope($o,$u,$role,$p);$name=$this->text($in['name']??null,180,'supplier_name_required');$level=$in['capabilityLevel']??null;if(!is_int($level)||$level<0||$level>6)throw new SupplierProcurementException('supplier_capability_level_invalid');$status=match($level){0=>'manual_ready',1=>'catalogue_upload_ready',default=>'integration_required'};$id=Identifier::generate();$this->pdo->prepare("INSERT INTO supplier_profiles(id,organisation_id,project_id,name,capability_level,connector_status,service_regions,contact_email,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:name,:level,:status,:regions,:email,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'name'=>$name,'level'=>$level,'status'=>$status,'regions'=>$this->json($this->strings($in['serviceRegions']??[])),'email'=>$this->optional($in['contactEmail']??null,320),'u'=>$u]);$this->event($o,$u,$role,$p,'supplier_registered','Supplier registered','approved',['supplierId'=>$id,'capabilityLevel'=>$level,'connectorStatus'=>$status],$id);return['id'=>$id,'name'=>$name,'capabilityLevel'=>$level,'connectorStatus'=>$status,'status'=>'active','version'=>1];}

    /** @param array<string,mixed>$in @return array<string,mixed> */public function importCatalogue(string$o,string$u,string$role,string$supplierId,array$in):array{$supplier=$this->supplier($o,$u,$role,$supplierId);if((int)$supplier['capability_level']>1)throw new SupplierProcurementException('supplier_connector_integration_required');$items=$in['items']??null;if(!is_array($items)||$items===[])throw new SupplierProcurementException('supplier_catalogue_items_required');$source=$this->choice($in['sourceKind']??null,['manual','csv_upload'],'supplier_catalogue_source_invalid');$file=is_string($in['sourceFileId']??null)?strtolower($in['sourceFileId']):null;if($source==='csv_upload'&&$file===null)throw new SupplierProcurementException('supplier_catalogue_source_file_required');if($file)$this->file((string)$supplier['organisation_id'],(string)$supplier['project_id'],$file);$key=$this->text($in['idempotencyKey']??null,120,'supplier_idempotency_key_required');$existing=$this->byIdempotency('supplier_catalogue_revisions',$o,$key);if($existing)return$existing;$normalised=[];foreach($items as$item){if(!is_array($item))throw new SupplierProcurementException('supplier_catalogue_item_invalid');$n=$this->normaliser->normalise($item);if($n['sku']===''||$n['name']===''||$n['category']===''||$n['unit']===''||$n['priceCents']<0||$n['stockQuantity']<0||$n['leadTimeDays']<0)throw new SupplierProcurementException('supplier_catalogue_item_invalid');if($n['datasheetFileId'])$this->file($o,(string)$supplier['project_id'],$n['datasheetFileId']);$normalised[]=$n;}$payload=['supplierId'=>$supplierId,'sourceKind'=>$source,'sourceFileId'=>$file,'items'=>$normalised];$sha=$this->sha($payload);$id=Identifier::generate();return$this->transaction(function()use($o,$u,$supplierId,$supplier,$source,$file,$key,$normalised,$payload,$sha,$id,$role):array{$next=$this->nextRevision('supplier_catalogue_revisions','supplier_id',$supplierId);$this->pdo->prepare("INSERT INTO supplier_catalogue_revisions(id,organisation_id,project_id,supplier_id,revision,source_kind,source_file_id,idempotency_key,snapshot_payload,snapshot_sha256,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:s),:revision,:source,UNHEX(:file),:key,:payload,:sha,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$supplier['project_id'],'s'=>$supplierId,'revision'=>$next,'source'=>$source,'file'=>$file,'key'=>$key,'payload'=>$this->json($payload),'sha'=>$sha,'u'=>$u]);$insert=$this->pdo->prepare("INSERT INTO supplier_catalogue_items(id,organisation_id,project_id,supplier_id,catalogue_revision_id,sku,name,category,unit,price_cents,stock_quantity,lead_time_days,standards,delivery_regions,datasheet_file_id,substitution_eligible) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:s),UNHEX(:r),:sku,:name,:category,:unit,:price,:stock,:lead,:standards,:regions,UNHEX(:file),:substitution)");foreach($normalised as$item)$insert->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$supplier['project_id'],'s'=>$supplierId,'r'=>$id,'sku'=>$item['sku'],'name'=>$item['name'],'category'=>$item['category'],'unit'=>$item['unit'],'price'=>$item['priceCents'],'stock'=>$item['stockQuantity'],'lead'=>$item['leadTimeDays'],'standards'=>$this->json($item['standards']),'regions'=>$this->json($item['deliveryRegions']),'file'=>$item['datasheetFileId'],'substitution'=>$item['substitutionEligible']?1:0]);$this->event($o,$u,$role,(string)$supplier['project_id'],'supplier_catalogue_revision','Supplier catalogue revision','issued',['catalogueRevisionId'=>$id,'supplierId'=>$supplierId,'revision'=>$next,'itemCount'=>count($normalised),'snapshotSha256'=>$sha],$id);return['id'=>$id,'supplierId'=>$supplierId,'revision'=>$next,'sourceKind'=>$source,'itemCount'=>count($normalised),'snapshotSha256'=>$sha];});}

    /** @param array<string,mixed>$in @return array<string,mixed> */
    public function createBaseline(string$o,string$u,string$role,string$p,array$in):array
    {
        $this->scope($o,$u,$role,$p);$title=$this->text($in['title']??null,220,'supplier_baseline_title_required');$files=$this->ids($in['sourceFileIds']??[]);foreach($files as$f)$this->file($o,$p,$f);$lines=$in['lines']??null;if(!is_array($lines)||$lines===[])throw new SupplierProcurementException('supplier_baseline_lines_required');
        $normal=[];foreach($lines as$line){if(!is_array($line))throw new SupplierProcurementException('supplier_baseline_line_invalid');$documents=$this->ids($line['sourceDocumentIds']??[]);foreach($documents as$document)$this->document($o,$p,$document);$normal[]=['sourceItemRef'=>$this->text($line['sourceItemRef']??null,160,'supplier_baseline_line_invalid'),'description'=>$this->text($line['description']??null,500,'supplier_baseline_line_invalid'),'category'=>strtolower($this->text($line['category']??null,120,'supplier_baseline_line_invalid')),'specification'=>$this->optional($line['specification']??null,500),'requiredStandard'=>$this->optional($line['requiredStandard']??null,180),'quantity'=>$this->positive($line['quantity']??null,'supplier_baseline_line_invalid'),'unit'=>strtolower($this->text($line['unit']??null,40,'supplier_baseline_line_invalid')),'allowSubstitution'=>($line['allowSubstitution']??false)===true,'requiredOnSiteDate'=>$this->date($line['requiredOnSiteDate']??null,'supplier_baseline_line_invalid'),'sourceDocumentIds'=>$documents];}
        $id=Identifier::generate();return$this->transaction(function()use($o,$u,$role,$p,$title,$files,$normal,$id):array{$this->pdo->prepare("INSERT INTO supplier_procurement_baselines(id,organisation_id,project_id,title,source_file_ids,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:title,:files,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'title'=>$title,'files'=>$this->json($files),'u'=>$u]);$insert=$this->pdo->prepare("INSERT INTO supplier_procurement_baseline_lines(id,organisation_id,project_id,baseline_id,source_item_ref,description,category,specification,required_standard,quantity,unit,allow_substitution,required_on_site_date,source_document_ids) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:baseline),:ref,:description,:category,:specification,:standard,:quantity,:unit,:allow,:required,:documents)");foreach($normal as$line)$insert->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'baseline'=>$id,'ref'=>$line['sourceItemRef'],'description'=>$line['description'],'category'=>$line['category'],'specification'=>$line['specification'],'standard'=>$line['requiredStandard'],'quantity'=>$line['quantity'],'unit'=>$line['unit'],'allow'=>$line['allowSubstitution']?1:0,'required'=>$line['requiredOnSiteDate'],'documents'=>$this->json($line['sourceDocumentIds'])]);$this->event($o,$u,$role,$p,'procurement_baseline','Procurement baseline draft','draft',['baselineId'=>$id,'lineCount'=>count($normal),'sourceFileIds'=>$files],$id);return['id'=>$id,'title'=>$title,'status'=>'draft','version'=>1,'lineCount'=>count($normal)];});
    }

    /** @param array<string,mixed>$in @return array<string,mixed> */public function approveBaseline(string$o,string$u,string$role,string$id,array$in):array{$this->approver($o,$u,$role);$this->confirmed($in,'supplier_baseline_confirmation_required');$reason=$this->text($in['reason']??null,1000,'supplier_baseline_reason_required');$version=$this->version($in);$row=$this->one("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,title,status,version,source_file_ids FROM supplier_procurement_baselines WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) FOR UPDATE",$o,$id,'supplier_baseline_not_found');if($row['status']!=='draft')throw new SupplierProcurementException('supplier_baseline_transition_invalid');if((int)$row['version']!==$version)throw new SupplierProcurementException('supplier_version_conflict');$lines=$this->baselineLines($o,$id);$payload=['baselineId'=>$id,'title'=>$row['title'],'sourceFileIds'=>$this->decode($row['source_file_ids']),'lines'=>$lines,'approvedBy'=>$u,'reason'=>$reason];$sha=$this->sha($payload);$this->pdo->prepare("UPDATE supplier_procurement_baselines SET status='approved',version=version+1,snapshot_payload=:payload,snapshot_sha256=:sha,approved_by=UNHEX(:u),approval_reason=:reason,approved_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND version=:version")->execute(['payload'=>$this->json($payload),'sha'=>$sha,'u'=>$u,'reason'=>$reason,'id'=>$id,'o'=>$o,'version'=>$version]);$this->event($o,$u,$role,(string)$row['project_id'],'procurement_baseline_approved','Procurement baseline approved','approved',['baselineId'=>$id,'snapshotSha256'=>$sha,'humanConfirmed'=>true],$id);return['id'=>$id,'status'=>'approved','version'=>$version+1,'snapshotSha256'=>$sha];}

    /** @param array<string,mixed>$in @return array<string,mixed> */public function buildPackage(string$o,string$u,string$role,string$baselineId,array$in):array{$baseline=$this->one("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,title,status,snapshot_sha256 FROM supplier_procurement_baselines WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)",$o,$baselineId,'supplier_baseline_not_found');$this->scope($o,$u,$role,(string)$baseline['project_id']);if($baseline['status']!=='approved'||!is_string($baseline['snapshot_sha256']))throw new SupplierProcurementException('supplier_approved_baseline_required');$title=$this->text($in['title']??null,220,'supplier_package_title_required');$region=strtolower($this->text($in['projectRegion']??null,120,'supplier_project_region_required'));$lines=$this->baselineLines($o,$baselineId);$payload=['baselineId'=>$baselineId,'baselineSha256'=>$baseline['snapshot_sha256'],'title'=>$title,'projectRegion'=>$region,'lines'=>$lines];$sha=$this->sha($payload);$id=Identifier::generate();return$this->transaction(function()use($o,$u,$role,$baselineId,$baseline,$title,$region,$lines,$payload,$sha,$id):array{try{$this->pdo->prepare("INSERT INTO supplier_integration_packages(id,organisation_id,project_id,baseline_id,title,project_region,status,snapshot_payload,snapshot_sha256,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:baseline),:title,:region,'procurement_package_created',:payload,:sha,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$baseline['project_id'],'baseline'=>$baselineId,'title'=>$title,'region'=>$region,'payload'=>$this->json($payload),'sha'=>$sha,'u'=>$u]);}catch(PDOException$e){if($e->getCode()==='23000')throw new SupplierProcurementException('supplier_package_exists');throw$e;}$insert=$this->pdo->prepare("INSERT INTO supplier_integration_package_lines(id,organisation_id,project_id,package_id,baseline_line_id,description,category,required_standard,quantity,unit,allow_substitution,required_on_site_date) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:package),UNHEX(:line),:description,:category,:standard,:quantity,:unit,:allow,:required)");foreach($lines as$line)$insert->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$baseline['project_id'],'package'=>$id,'line'=>$line['id'],'description'=>$line['description'],'category'=>$line['category'],'standard'=>$line['requiredStandard'],'quantity'=>$line['quantity'],'unit'=>$line['unit'],'allow'=>$line['allowSubstitution']?1:0,'required'=>$line['requiredOnSiteDate']]);$this->event($o,$u,$role,(string)$baseline['project_id'],'supplier_procurement_package','Supplier procurement package','issued',['packageId'=>$id,'baselineId'=>$baselineId,'snapshotSha256'=>$sha],$id);return['id'=>$id,'baselineId'=>$baselineId,'title'=>$title,'status'=>'procurement_package_created','version'=>1,'lineCount'=>count($lines),'snapshotSha256'=>$sha];});}

    /** @return list<array<string,mixed>> */public function matchCatalogue(string$o,string$u,string$role,string$packageId):array{$package=$this->package($o,$u,$role,$packageId);$lines=$this->packageLines($o,$packageId);$catalogue=$this->latestCatalogue($o,(string)$package['project_id']);$now=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d');return$this->transaction(function()use($o,$u,$role,$packageId,$package,$lines,$catalogue,$now):array{$insert=$this->pdo->prepare("INSERT INTO supplier_catalogue_matches(id,organisation_id,project_id,package_id,package_line_id,catalogue_item_id,score,risk_flags,latest_order_date,advisory_only,price_cents_snapshot,stock_quantity_snapshot,lead_time_days_snapshot,snapshot_sha256) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:package),UNHEX(:line),UNHEX(:item),:score,:risk,:latest,TRUE,:price,:stock,:lead,:sha) ON DUPLICATE KEY UPDATE score=VALUES(score),risk_flags=VALUES(risk_flags),latest_order_date=VALUES(latest_order_date),price_cents_snapshot=VALUES(price_cents_snapshot),stock_quantity_snapshot=VALUES(stock_quantity_snapshot),lead_time_days_snapshot=VALUES(lead_time_days_snapshot),snapshot_sha256=VALUES(snapshot_sha256)");foreach($lines as$line)foreach($catalogue as$item){$score=$this->normaliser->score($line,$item,(string)$package['project_region'],$now);if($score['score']<20)continue;$payload=['packageLineId'=>$line['id'],'catalogueItemId'=>$item['id'],'score'=>$score,'priceCents'=>$item['priceCents'],'stockQuantity'=>$item['stockQuantity'],'leadTimeDays'=>$item['leadTimeDays']];$insert->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$package['project_id'],'package'=>$packageId,'line'=>$line['id'],'item'=>$item['id'],'score'=>$score['score'],'risk'=>$this->json($score['riskFlags']),'latest'=>$score['latestOrderDate'],'price'=>$item['priceCents'],'stock'=>$item['stockQuantity'],'lead'=>$item['leadTimeDays'],'sha'=>$this->sha($payload)]);}$this->pdo->prepare("UPDATE supplier_integration_packages SET status='supplier_matching_in_progress',version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)")->execute(['id'=>$packageId,'o'=>$o]);$this->event($o,$u,$role,(string)$package['project_id'],'supplier_matching','Advisory supplier matching','pending_review',['packageId'=>$packageId,'advisoryOnly'=>true],$packageId);return$this->matches($o,$packageId);});}

    /** @param array<string,mixed>$in @return array<string,mixed> */
    public function issueRfq(string$o,string$u,string$role,string$packageId,array$in):array
    {
        $package=$this->package($o,$u,$role,$packageId);if(!in_array($package['status'],['supplier_matching_in_progress','rfq_issued','quote_comparison_ready'],true))throw new SupplierProcurementException('supplier_rfq_transition_invalid');$this->confirmed($in,'supplier_rfq_confirmation_required');
        $supplierId=$this->id($in['supplierId']??null,'supplier_not_found');$supplier=$this->supplier($o,$u,$role,$supplierId);if($supplier['project_id']!==$package['project_id'])throw new SupplierProcurementException('supplier_not_found');$days=$in['expiresInDays']??14;if(!is_int($days)||$days<1||$days>90)throw new SupplierProcurementException('supplier_rfq_expiry_invalid');
        $token=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$id=Identifier::generate();$expires=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->modify('+'.$days.' days')->format('Y-m-d H:i:s.u');
        $this->pdo->prepare("INSERT INTO supplier_rfqs(id,organisation_id,project_id,package_id,supplier_id,token_hash,expires_at,issued_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:package),UNHEX(:supplier),:hash,:expires,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$package['project_id'],'package'=>$packageId,'supplier'=>$supplierId,'hash'=>hash('sha256',$token),'expires'=>$expires,'u'=>$u]);
        $this->pdo->prepare("UPDATE supplier_integration_packages SET status='rfq_issued',version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)")->execute(['id'=>$packageId,'o'=>$o]);$this->event($o,$u,$role,(string)$package['project_id'],'supplier_rfq_issued','Supplier RFQ issued','issued',['rfqId'=>$id,'supplierId'=>$supplierId,'tokenStoredAsHash'=>true],$id);
        return['id'=>$id,'status'=>'issued','expiresAt'=>$expires,'accessToken'=>$token,'accessTokenShownOnce'=>true];
    }

    /** @param array<string,mixed>$in @return array<string,mixed> */
    public function revokeRfq(string$o,string$u,string$role,string$rfqId,array$in):array
    {
        $this->approver($o,$u,$role);$this->confirmed($in,'supplier_rfq_revocation_confirmation_required');$reason=$this->text($in['reason']??null,1000,'supplier_rfq_revocation_reason_required');
        $rfq=$this->one("SELECT LOWER(HEX(r.id)) id,LOWER(HEX(r.project_id)) project_id,r.status,p.status package_status FROM supplier_rfqs r JOIN supplier_integration_packages p ON p.id=r.package_id AND p.organisation_id=r.organisation_id WHERE r.id=UNHEX(:id) AND r.organisation_id=UNHEX(:o)",$o,$rfqId,'supplier_rfq_not_found');
        if(!in_array($rfq['status'],['issued','viewed','quote_submitted'],true)||!in_array($rfq['package_status'],['rfq_issued','quote_comparison_ready'],true))throw new SupplierProcurementException('supplier_rfq_transition_invalid');
        $this->pdo->prepare("UPDATE supplier_rfqs SET status='revoked' WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND status IN ('issued','viewed','quote_submitted')")->execute(['id'=>$rfqId,'o'=>$o]);
        $this->event($o,$u,$role,(string)$rfq['project_id'],'supplier_rfq_revoked','Supplier RFQ revoked','rejected',['rfqId'=>$rfqId,'reason'=>$reason,'humanConfirmed'=>true],$rfqId);return['id'=>$rfqId,'status'=>'revoked','reason'=>$reason];
    }

    /** @param array<string,mixed>$in @return array<string,mixed> */
    public function submitQuote(string$token,array$in):array
