        $this->pdo->prepare("UPDATE supplier_integration_packages SET status='delivery_in_progress',version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)")->execute(['id'=>$po['package_id'],'o'=>$o]);
        $recordStatus=$status==='rejected_or_partial'?'rejected':'issued';$this->event($o,$u,$role,(string)$po['project_id'],'supplier_delivery','Supplier delivery '.$status,$recordStatus,['deliveryId'=>$id,'purchaseOrderId'=>$poId,'status'=>$status,'evidenceFileIds'=>$files],$id);
        return['id'=>$id,'purchaseOrderId'=>$poId,'deliveryReference'=>$reference,'status'=>$status,'version'=>1];
    }

