        $this->event($o,$u,$role,(string)$invoice['project_id'],'supplier_payment_recommendation','Supplier payment recommendation',$allowed?'pending_review':'rejected',['paymentRecommendationId'=>$id]+$payload,$id);return['id'=>$id,'invoiceId'=>$invoiceId,'decision'=>$decision,'reason'=>$reason,'providerStatus'=>'integration_required','movesMoney'=>false,'snapshotSha256'=>$sha];
