    /** @return array<string,mixed> */private function supplier(string$o,string$u,string$role,string$id):array{$row=$this->one("SELECT LOWER(HEX(id)) id,LOWER(HEX(organisation_id)) organisation_id,LOWER(HEX(project_id)) project_id,name,capability_level,connector_status,status FROM supplier_profiles WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)",$o,$id,'supplier_not_found');$this->scope($o,$u,$role,(string)$row['project_id']);return$row;}
    /** @return array<string,mixed> */private function package(string$o,string$u,string$role,string$id):array{$row=$this->one("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,LOWER(HEX(baseline_id)) baseline_id,title,project_region,status,version,snapshot_sha256 FROM supplier_integration_packages WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)",$o,$id,'supplier_package_not_found');$this->scope($o,$u,$role,(string)$row['project_id']);return$row;}
    /** @return array<string,mixed> */private function purchaseOrder(string$o,string$u,string$role,string$id):array{$row=$this->one("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,LOWER(HEX(package_id)) package_id,status,total_cents FROM supplier_purchase_orders WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)",$o,$id,'supplier_purchase_order_not_found');$this->scope($o,$u,$role,(string)$row['project_id']);return$row;}
    /** @return array<string,mixed> */private function delivery(string$o,string$u,string$role,string$id):array{$row=$this->one("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,LOWER(HEX(purchase_order_id)) purchase_order_id,status FROM supplier_deliveries WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)",$o,$id,'supplier_delivery_not_found');$this->scope($o,$u,$role,(string)$row['project_id']);return$row;}
    /** @return array<string,mixed> */private function rfqByToken(string$token):array{if(preg_match('/\A[A-Za-z0-9_-]{43}\z/',$token)!==1)throw new SupplierProcurementException('supplier_rfq_not_found');$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(organisation_id)) organisation_id,LOWER(HEX(project_id)) project_id,LOWER(HEX(package_id)) package_id,LOWER(HEX(supplier_id)) supplier_id,LOWER(HEX(issued_by)) issued_by,status,expires_at FROM supplier_rfqs WHERE token_hash=:hash AND status IN ('issued','viewed','quote_submitted')");$s->execute(['hash'=>hash('sha256',$token)]);$r=$s->fetch();if(!is_array($r)||new DateTimeImmutable((string)$r['expires_at'],new DateTimeZone('UTC'))<new DateTimeImmutable('now',new DateTimeZone('UTC')))throw new SupplierProcurementException('supplier_rfq_not_found');return$r;}
    /** @param array<string,mixed>$rfq @return array<string,mixed>|null */private function purchaseOrderForRfq(array$rfq):?array{$s=$this->pdo->prepare("SELECT LOWER(HEX(po.id)) id,po.order_number orderNumber,po.status,po.total_cents totalCents,a.snapshot_payload awardPayload FROM supplier_purchase_orders po JOIN supplier_award_decisions a ON a.id=po.award_id AND a.organisation_id=po.organisation_id WHERE po.organisation_id=UNHEX(:o) AND po.package_id=UNHEX(:package) ORDER BY po.issued_at DESC LIMIT 1");$s->execute(['o'=>$rfq['organisation_id'],'package'=>$rfq['package_id']]);$po=$s->fetch();if(!is_array($po))return null;$award=$this->decode($po['awardPayload']);$selected=$award['selectedMatches']??[];if(!is_array($selected)||$selected===[])return null;foreach($selected as$match)if(!is_array($match)||($match['supplier_id']??null)!==$rfq['supplier_id'])return null;unset($po['awardPayload']);$po['totalCents']=(int)$po['totalCents'];return$po;}
    /** @return list<array<string,mixed>> */private function baselineLines(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,source_item_ref sourceItemRef,description,category,specification,required_standard requiredStandard,quantity,unit,allow_substitution allowSubstitution,required_on_site_date requiredOnSiteDate,source_document_ids sourceDocumentIds FROM supplier_procurement_baseline_lines WHERE organisation_id=UNHEX(:o) AND baseline_id=UNHEX(:id) ORDER BY created_at,id");$s->execute(['o'=>$o,'id'=>$id]);$rows=$s->fetchAll();foreach($rows as&$r){$r['quantity']=(float)$r['quantity'];$r['allowSubstitution']=(bool)$r['allowSubstitution'];$r['sourceDocumentIds']=$this->decode($r['sourceDocumentIds']);}return$rows;}
    /** @return list<array<string,mixed>> */private function packageLines(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,description,category,required_standard requiredStandard,quantity,unit,allow_substitution allowSubstitution,required_on_site_date requiredOnSiteDate FROM supplier_integration_package_lines WHERE organisation_id=UNHEX(:o) AND package_id=UNHEX(:id) ORDER BY created_at,id");$s->execute(['o'=>$o,'id'=>$id]);$rows=$s->fetchAll();foreach($rows as&$r){$r['quantity']=(float)$r['quantity'];$r['allowSubstitution']=(bool)$r['allowSubstitution'];}return$rows;}
    /** @return list<array<string,mixed>> */private function latestCatalogue(string$o,string$p):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(i.id)) id,i.sku,i.name,i.category,i.unit,i.price_cents priceCents,i.stock_quantity stockQuantity,i.lead_time_days leadTimeDays,i.standards,i.delivery_regions deliveryRegions,i.substitution_eligible substitutionEligible FROM supplier_catalogue_items i JOIN supplier_catalogue_revisions r ON r.id=i.catalogue_revision_id AND r.organisation_id=i.organisation_id WHERE i.organisation_id=UNHEX(:o) AND i.project_id=UNHEX(:p) AND r.revision=(SELECT MAX(r2.revision) FROM supplier_catalogue_revisions r2 WHERE r2.supplier_id=r.supplier_id)");$s->execute(['o'=>$o,'p'=>$p]);$rows=$s->fetchAll();foreach($rows as&$r){$r['priceCents']=(int)$r['priceCents'];$r['stockQuantity']=(float)$r['stockQuantity'];$r['leadTimeDays']=(int)$r['leadTimeDays'];$r['standards']=$this->decode($r['standards']);$r['deliveryRegions']=$this->decode($r['deliveryRegions']);$r['substitutionEligible']=(bool)$r['substitutionEligible'];}return$rows;}
    /** @return list<array<string,mixed>> */private function matches(string$o,string$package):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(package_line_id)) packageLineId,LOWER(HEX(catalogue_item_id)) catalogueItemId,score,risk_flags riskFlags,latest_order_date latestOrderDate,advisory_only advisoryOnly,price_cents_snapshot priceCents,snapshot_sha256 snapshotSha256 FROM supplier_catalogue_matches WHERE organisation_id=UNHEX(:o) AND package_id=UNHEX(:package) ORDER BY package_line_id,score DESC");$s->execute(['o'=>$o,'package'=>$package]);$rows=$s->fetchAll();foreach($rows as&$r){$r['score']=(int)$r['score'];$r['riskFlags']=$this->decode($r['riskFlags']);$r['advisoryOnly']=(bool)$r['advisoryOnly'];$r['priceCents']=(int)$r['priceCents'];}return$rows;}
    private function approvedSubstitution(string$o,string$match):bool{$s=$this->pdo->prepare("SELECT COUNT(*) FROM supplier_substitution_decisions WHERE organisation_id=UNHEX(:o) AND match_id=UNHEX(:match) AND decision='approved'");$s->execute(['o'=>$o,'match'=>$match]);return(int)$s->fetchColumn()===1;}
    private function scope(string$o,string$u,string$claimed,string$p,bool$allowViewer=false):void{$s=$this->pdo->prepare("SELECT m.role FROM organisation_memberships m JOIN projects p ON p.organisation_id=m.organisation_id WHERE m.organisation_id=UNHEX(:o) AND m.user_id=UNHEX(:u) AND m.status='active' AND p.id=UNHEX(:p) AND p.organisation_id=m.organisation_id");$s->execute(['o'=>$o,'u'=>$u,'p'=>$this->id($p,'supplier_project_not_found')]);$actual=$s->fetchColumn();if(!is_string($actual)||!hash_equals($actual,$claimed)||!in_array($actual,['owner','admin','member','viewer'],true)||$actual==='viewer'&&!$allowViewer)throw new SupplierProcurementException('supplier_permission_denied');}
    private function approver(string$o,string$u,string$claimed):void{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);$actual=$s->fetchColumn();if(!is_string($actual)||!hash_equals($actual,$claimed)||!in_array($actual,['owner','admin'],true))throw new SupplierProcurementException('supplier_approval_forbidden');}
    private function roleFor(string$o,string$u):string{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);$role=$s->fetchColumn();if(!is_string($role))throw new SupplierProcurementException('supplier_permission_denied');return$role;}
    private function file(string$o,string$p,string$id):void{$s=$this->pdo->prepare("SELECT COUNT(*) FROM stored_files WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND project_id=UNHEX(:p)");$s->execute(['id'=>$this->id($id,'supplier_file_not_found'),'o'=>$o,'p'=>$p]);if((int)$s->fetchColumn()!==1)throw new SupplierProcurementException('supplier_file_not_found');}
    private function document(string$o,string$p,string$id):void{$s=$this->pdo->prepare("SELECT COUNT(*) FROM controlled_documents WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND project_id=UNHEX(:p)");$s->execute(['id'=>$this->id($id,'supplier_document_not_found'),'o'=>$o,'p'=>$p]);if((int)$s->fetchColumn()!==1)throw new SupplierProcurementException('supplier_document_not_found');}
    /** @return array<string,mixed> */private function one(string$sql,string$o,string$id,string$error):array{$s=$this->pdo->prepare($sql);$s->execute(['o'=>$o,'id'=>$this->id($id,$error)]);$r=$s->fetch();if(!is_array($r))throw new SupplierProcurementException($error);return$r;}
    /** @param list<string>$jsonFields @return list<array<string,mixed>> */private function rows(string$sql,string$o,string$p,array$jsonFields=[]):array{$s=$this->pdo->prepare($sql);$s->execute(['o'=>$o,'p'=>$p]);$rows=$s->fetchAll();foreach($rows as&$r)foreach($jsonFields as$f)$r[$f]=$this->decode($r[$f]??null);return$rows;}
    /** @return array<string,mixed>|null */private function byIdempotency(string$table,string$o,string$key):?array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id FROM $table WHERE organisation_id=UNHEX(:o) AND idempotency_key=:key LIMIT 1");$s->execute(['o'=>$o,'key'=>$key]);$id=$s->fetchColumn();return is_string($id)?['id'=>$id,'idempotentReplay'=>true]:null;}
    private function nextRevision(string$table,string$field,string$id):int{$s=$this->pdo->prepare("SELECT COALESCE(MAX(revision),0)+1 FROM $table WHERE $field=UNHEX(:id)");$s->execute(['id'=>$id]);return(int)$s->fetchColumn();}
    /** @param array<string,mixed>$in */private function confirmed(array$in,string$error):void{if(($in['humanConfirmed']??false)!==true)throw new SupplierProcurementException($error);}
    /** @param array<string,mixed>$in */private function version(array$in):int{$v=$in['expectedVersion']??null;if(!is_int($v)||$v<1)throw new SupplierProcurementException('supplier_expected_version_required');return$v;}
    private function text(mixed$v,int$max,string$error):string{if(!is_string($v)||trim($v)===''||mb_strlen(trim($v))>$max)throw new SupplierProcurementException($error);return trim($v);}private function optional(mixed$v,int$max):?string{if($v===null||$v==='')return null;if(!is_string($v)||mb_strlen(trim($v))>$max)throw new SupplierProcurementException('supplier_value_invalid');return trim($v);}
    private function choice(mixed$v,array$allowed,string$error):string{if(!is_string($v)||!in_array($v,$allowed,true))throw new SupplierProcurementException($error);return$v;}private function positive(mixed$v,string$error):float{if((!is_int($v)&&!is_float($v))||!is_finite((float)$v)||(float)$v<=0)throw new SupplierProcurementException($error);return(float)$v;}
    private function date(mixed$v,string$error):string{if(!is_string($v)||preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$v)!==1)throw new SupplierProcurementException($error);try{$d=new DateTimeImmutable($v,new DateTimeZone('UTC'));}catch(Throwable){throw new SupplierProcurementException($error);}return$d->format('Y-m-d');}
    private function id(mixed$v,string$error):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new SupplierProcurementException($error);return strtolower($v);}
    /** @return list<string> */private function ids(mixed$v):array{if(!is_array($v))throw new SupplierProcurementException('supplier_ids_invalid');$out=[];foreach($v as$id)$out[]=$this->id($id,'supplier_ids_invalid');return array_values(array_unique($out));}/** @return list<string> */private function strings(mixed$v):array{if(!is_array($v))throw new SupplierProcurementException('supplier_values_invalid');$out=[];foreach($v as$x)if(is_string($x)&&trim($x)!=='')$out[]=trim($x);return array_values(array_unique($out));}
    /** @param array<mixed>$v */private function json(array$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION|JSON_UNESCAPED_UNICODE);}/** @return array<mixed> */private function decode(mixed$v):array{if(!is_string($v))return[];$d=json_decode($v,true,64,JSON_THROW_ON_ERROR);return is_array($d)?$d:[];}/** @param array<mixed>$payload */private function sha(array$payload):string{return hash('sha256',$this->json($payload));}
    /** @param array<string,mixed>$payload */private function event(string$o,string$u,string$role,string$p,string$type,string$title,string$status,array$payload,string$subject):void{$context=new ProjectContext($o,$u,$p,$role);(new ProjectRecordService($this->pdo))->issue($context,in_array($type,['supplier_delivery','supplier_site_acceptance'],true)?ProjectPhase::ConstructionExecution:ProjectPhase::TenderProcurement,self::MODULE,$type,$title,$status,$payload,['required'=>str_contains($type,'approval')||str_contains($type,'decision'),'humanConfirmed'=>$payload['humanConfirmed']??false],[$subject]);(new InboxService($this->pdo))->create($context,self::MODULE.'.'.$type,$title,(string)($payload['reason']??$title),in_array($status,['rejected','pending_review'],true)?'high':'medium',$payload);(new AuditService($this->pdo))->append($o,$u,self::MODULE.'.'.$type,$type,$subject,$payload);}
    /** @template T @param callable():T$callback @return T */private function transaction(callable$callback):mixed{$owned=!$this->pdo->inTransaction();if($owned)$this->pdo->beginTransaction();try{$result=$callback();if($owned)$this->pdo->commit();return$result;}catch(Throwable$e){if($owned&&$this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
